const $=id=>document.getElementById(id),game=new Adventure();const music=new GameMusic();let last=0,held=0,keyHeld=0,gamepadA=false,walking=false,helpPhase=null,walkFrame=-1;
const art={'book':'book','toy':'toy','shoes':'shoes','hat':'hat','terracotta plant':'plant-terracotta','blue plant':'plant-blue','yellow leaf':'leaf-yellow','green leaf':'leaf-green','cupcake':'cupcake','muffin':'muffin','magnifying glass':'magnifier','key':'key'};
const image=(item)=>`<img src="assets/${art[item]}.png" alt="${item}">`;
function fit(){
 const viewport=$('viewport'),visual=window.visualViewport;
 const width=Math.min(viewport.clientWidth,visual?.width||innerWidth);
 const height=Math.min(viewport.clientHeight,visual?.height||innerHeight);
 const scale=Math.min(width/1600,height/900),stage=$('game');
 stage.style.width=`${width/scale}px`;
 stage.style.height=`${height/scale}px`;
 stage.style.left=`${visual?.offsetLeft||0}px`;
 stage.style.top=`${visual?.offsetTop||0}px`;
 stage.style.transform=`scale(${scale})`;held=keyHeld=0;
}
addEventListener('resize',fit);
addEventListener('orientationchange',()=>{fit();setTimeout(fit,150);setTimeout(fit,400)});
document.addEventListener('fullscreenchange',()=>requestAnimationFrame(fit));
window.visualViewport?.addEventListener('resize',fit);
window.visualViewport?.addEventListener('scroll',fit);
fit();
// Holding a game control must never open Android's image/context menu.
for(const event of ['contextmenu','dragstart','selectstart']) $('game').addEventListener(event,e=>e.preventDefault(),{capture:true});
document.querySelectorAll('#game img').forEach(img=>img.draggable=false);
const sceneImages=[];
for(const src of ['assets/kitchen-finale.webp?v=7',...Array.from({length:6},(_,i)=>`assets/room-${i}.webp`)]){
 const image=new Image();image.src=src;image.decoding='async';sceneImages.push(image);
 if(image.decode)image.decode().catch(()=>{});
}
async function fullscreen(){try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();if(screen.orientation?.lock)await screen.orientation.lock('landscape')}catch{/* Browser-dependent: the landscape prompt remains available. */}}
$('fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});else fullscreen()};
function sound(success=true){if(success)music.victory();else music.wrong()}
$('sound').onclick=async()=>{const on=await music.toggle();$('sound').textContent=on?'♫':'♪';$('sound').setAttribute('aria-pressed',String(on));$('sound').setAttribute('aria-label',on?'Turn music off':'Turn music on')};
function modal(html){held=keyHeld=0;$('overlay').hidden=false;$('modal').innerHTML=html;requestAnimationFrame(()=>$('modal').querySelector('button')?.focus())}
function hideModal(){$('overlay').hidden=true;$('select').focus({preventScroll:true})}
function intro(){modal(`<span class="eyebrow">A WONDER QUEST ADVENTURE</span><h2 id="modalTitle">The cosy house of clues</h2><div class="intro-content"><img class="uncle" src="assets/uncle.png" alt="Their detective uncle, a bear in a blue suit"><div><blockquote>“Toby, Finn and Milo! I have hidden patterns around the house. Solve my six cases and earn your cyber detective badges!”</blockquote><p class="signature">— Your detective uncle</p></div></div><div class="hero-team"><img src="assets/toby.png" alt="Toby the fox"><img src="assets/flint.png" alt="Finn the bunny"><img src="assets/milo.png" alt="Milo the mouse"></div><button class="primary" id="start">Click to start ✦</button><small>Hold ◀ or ▶ to walk. Press the hand next to your answer. Six rooms · Two puzzles in each.</small>`);$('start').onclick=()=>{fullscreen();music.start();game.start();hideModal();render()}}
function render(){const d=game.data;$('background').src=`assets/room-${game.level}.webp`;$('background').alt=`Warm storybook ${d.room.toLowerCase()}`;$('levelLabel').textContent=`LEVEL ${game.level+1} / 6`;$('roomLabel').textContent=d.room;$('roundLabel').textContent=`${d.hero.toUpperCase()}’S CLUE ${game.round+1} / 2`;$('sprite').src=`assets/${d.sprite}.png`;$('sprite').alt=d.hero;$('walkSprite').src=`assets/${d.sprite}-walk-0.png`;walkFrame=-1;walking=false;$('player').classList.remove('walking');faceIntoGame();$('playerName').textContent=d.hero;$('pattern').innerHTML=game.sequence.map(s=>`<div class="pattern-tile">${image(s)}</div>`).join('')+'<div class="pattern-tile unknown" aria-label="Missing object">?</div>';$('choices').innerHTML=game.options.map((s,i)=>`<div class="choice" style="left:${game.positions[i]}%" data-option="${i}">${image(s)}<span>${s[0].toUpperCase()+s.slice(1)}</span></div>`).join('');$('medals').innerHTML=game.medals.map((m,i)=>`<span class="medal ${m?'':'empty'}" role="img" aria-label="Level ${i+1} medal ${m?'earned':'not yet earned'}">★</span>`).join('');$('status').textContent=`Help ${d.hero}: walk to the object that comes next.`;position();}
function position(){const n=game.nearest;$('player').style.left=game.x+'%';document.querySelectorAll('.choice').forEach((c,i)=>c.classList.toggle('near',i===n));$('select').disabled=game.phase!=='play';$('select').classList.toggle('ready',n>=0&&game.phase==='play');$('select').setAttribute('aria-label',n<0?'Walk closer to an object':`Choose ${game.options[n]}`)}
function choose(){const result=game.choose();if(result==='blocked')return;if(result==='far'){$('status').textContent='Walk closer to an object, then press the hand.';return}if(result==='wrong'){$('status').textContent='Try again! The two objects take turns.';document.querySelectorAll('.choice')[game.nearest]?.classList.add('wrong');sound(false);return}held=keyHeld=0;position();sound();$('pattern').lastElementChild.innerHTML=image(game.answer);$('pattern').lastElementChild.classList.remove('unknown');document.querySelectorAll('.choice')[game.nearest]?.classList.add('correct');$('status').textContent='You found the pattern!';setTimeout(reward,650)}
function reward(){if(game.phase!=='reward')return;const finished=game.round===1;modal(`<div class="reward">${finished?'🏅':'✦'}</div><span class="eyebrow">${finished?'A MEDAL FOR YOUR TEAM':'CLUE SOLVED'}</span><h2 id="modalTitle">Brilliant spotting, ${game.data.hero}!</h2><p>${finished?'Both patterns solved. Another room explored!':'You found the next object. Ready for one more?'}</p><button class="primary" id="continue">${finished?(game.level===5?'Meet Detective Uncle →':'Next room →'):'Next pattern →'}</button>`);$('continue').onclick=()=>{game.next();if(game.phase==='final'){finale();return}render();if(game.phase==='room'){roomIntro()}else hideModal()}}
function roomIntro(){modal(`<span class="eyebrow">LEVEL ${game.level+1} OF 6</span><h2 id="modalTitle">${game.data.room}</h2><img src="assets/${game.data.sprite}.png" style="height:220px;width:175px;object-fit:contain" alt="${game.data.hero}"><p><b>It’s ${game.data.hero}’s turn!</b><br>${game.data.intro}</p><button class="primary" id="enter">Let’s explore →</button>`);$('enter').onclick=()=>{game.start();hideModal();render()}}
function finale(){music.victory(true);$('overlay').classList.add('celebrating');$('modal').classList.add('final-modal');modal(`<img class="kitchen-celebration" fetchpriority="high" decoding="sync" src="assets/kitchen-finale.webp?v=7" alt="Toby, Finn and Milo seated happily with badges at the kitchen table while Detective Uncle stands warmly behind them, with cakes and muffins on the table"><div class="final-heading"><span class="eyebrow">SIX MEDALS · TWELVE PATTERNS</span><h2 id="modalTitle">Official cyber detectives!</h2></div><div class="final-footer"><p>“Well done, detectives! Let’s celebrate together.”</p><button class="primary" id="replay">Play again ↻</button><p class="final-lesson">Stop, think and ask a trusted grown-up.</p></div>`);$('replay').onclick=()=>{$('overlay').classList.remove('celebrating');$('modal').classList.remove('final-modal');game.reset();render();intro()}}
$('help').onclick=()=>{if(game.phase==='reward'||game.phase==='final'||!$('overlay').hidden)return;helpPhase=game.phase;game.phase='help';modal(`<span class="eyebrow">DETECTIVE’S GUIDE</span><h2 id="modalTitle">Walk. Look. Choose.</h2><p>Look at the two objects in the pattern. They take turns.<br>Hold ◀ or ▶ to move your character.<br>Stand near your answer and press the green hand button.</p><p>On a keyboard, use ← → and Space.<br>A connected controller can use its stick or D-pad and A.</p><button class="primary" id="resume">Back to the game</button>`);$('resume').onclick=()=>{game.phase=helpPhase;hideModal();position()}};
function bindHold(id,direction){const el=$(id);el.onpointerdown=e=>{e.preventDefault();if(game.phase!=='play')return;held=direction;el.setPointerCapture(e.pointerId);el.classList.add('pressed')};const release=()=>{held=0;el.classList.remove('pressed')};el.onpointerup=release;el.onpointercancel=release;el.onlostpointercapture=release;}
bindHold('left',-1);bindHold('right',1);$('select').onclick=choose;
addEventListener('keydown',e=>{if(!$('overlay').hidden){if(e.key==='Tab'){const buttons=[...$('modal').querySelectorAll('button')];if(buttons.length){e.preventDefault();buttons[0].focus()}}return}if(['ArrowLeft','ArrowRight',' ','Enter'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')keyHeld=-1;if(e.key==='ArrowRight')keyHeld=1;if((e.key===' '||e.key==='Enter')&&!e.repeat)choose()});addEventListener('keyup',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight')keyHeld=0});addEventListener('blur',()=>{held=keyHeld=0});document.addEventListener('visibilitychange',()=>{held=keyHeld=0;if(document.hidden)music.pause();else music.resume()});
function face(direction){const scale=direction<0?'-1 1':'1 1';$('sprite').style.scale=scale;$('walkSprite').style.scale=scale}
function faceIntoGame(){face(game.x>50?-1:1)}
const walkImages=[];for(const name of ['toby','flint','milo'])for(let i=0;i<4;i++){const im=new Image();im.src=`assets/${name}-walk-${i}.png`;walkImages.push(im)}
function tick(now){const dt=Math.min((now-last)/1000,.05);last=now;let dir=held||keyHeld;let pad;try{pad=Array.from(navigator.getGamepads?.()??[]).find(Boolean)}catch{}if(pad&&document.getElementById('safetyWelcome')?.hidden!==false){const axis=pad.axes[0]||0;if(!dir)dir=pad.buttons[14]?.pressed?-1:pad.buttons[15]?.pressed?1:Math.abs(axis)>.25?axis:0;const a=!!pad.buttons[0]?.pressed;if(a&&!gamepadA){if(game.phase==='play')choose();else $('modal').querySelector('button')?.click()}gamepadA=a}const moving=game.phase==='play'&&dir!==0&&innerWidth>innerHeight;if(moving){game.move(dir*24*dt);face(dir);position();const frame=Math.floor(now/150)%4;if(frame!==walkFrame){walkFrame=frame;$('walkSprite').src=`assets/${game.data.sprite}-walk-${frame}.png`}}if(walking!==moving){walking=moving;$('player').classList.toggle('walking',moving);if(!moving){faceIntoGame();walkFrame=-1}}requestAnimationFrame(tick)}
render();intro();requestAnimationFrame(tick);
